// Webtoon strip layout: storyboard + character pins (NovelAI coords) -> 690 px strip geometry.
// Port of webtoon-bench/scripts/layout.py (coordinates variant, no Jev faces). Pure and deterministic.
//
// font-metrics.json is generated by a throwaway script (webtoon-inlay-work/gen_font_metrics.py) from
// webtoon-bench/fonts with fontTools: per font unitsPerEm, hmtx advances for U+0020-U+007E ("ascii"),
// a few punctuation/accented extras, and OS/2 xAvgCharWidth as the default advance.
import type { LayoutItem, LayoutPanel, Point, Rect, StripLayout } from "../../shared/contract/webtoon.js";
import metricsJson from "./font-metrics.json" with { type: "json" };

export type TextType = "speech" | "thought" | "narration" | "sfx";

export interface LayoutCharacterIn { name: string; x: number; y: number; framing?: string }
export interface LayoutTextIn { type: TextType; speaker?: string | null; text: string; anchor?: string }
export interface LayoutPanelIn {
  id: number | string;
  kind: "image" | "text_beat";
  beat?: string;
  layout?: string;
  scene_change?: boolean;
  size?: string;
  nai?: { characters: LayoutCharacterIn[] };
  text: LayoutTextIn[];
}
export interface LayoutInput {
  storyboard: { title?: string; panels: LayoutPanelIn[] };
  imageSizes: Record<string, { width: number; height: number }>;
}

const W = 690;
const LH_SPEECH = 22;
const LH_NARR = 24;
const SFX_FONT_PX = 56;
export const SFX_COLORS = ["#ff5c8a", "#ffc93c", "#5ad1ff", "#ff7a3c"];
// framing -> [max half-height of the body box around the pin, face height], fractions of image height.
const HEAD: Record<string, [number, number]> = {
  portrait: [0.5, 0.38],
  "upper body": [0.35, 0.18],
  "cowboy shot": [0.32, 0.14],
  "full body": [0.32, 0.1],
};
const MAX_PANEL_H = 1100;

// ---------- text ----------
type FontKey = "speech" | "narration" | "sfx";
interface FontMetrics { unitsPerEm: number; default: number; ascii: number[]; extra: Record<string, number> }
const METRICS: Record<FontKey, FontMetrics> = metricsJson;
const FONT_PX: Record<FontKey, number> = { speech: 19, narration: 20, sfx: SFX_FONT_PX };

// PIL (basic layout, no kerning) sums hinted advances, which equal the per-glyph rounded advance for
// these fonts; rounding per glyph keeps line breaks identical to the bench.
function textWidth(font: FontKey, text: string): number {
  const m = METRICS[font];
  const px = FONT_PX[font];
  let w = 0;
  for (const ch of text) {
    const c = ch.codePointAt(0)!;
    const adv = c >= 32 && c <= 126 ? m.ascii[c - 32]! : (m.extra[ch] ?? m.default);
    w += Math.round((adv * px) / m.unitsPerEm);
  }
  return w;
}

function wrap(text: string, font: FontKey, maxw: number): string[] {
  const lines: string[] = [];
  let cur = "";
  for (const word of text.split(/\s+/).filter(Boolean)) {
    const t = cur ? `${cur} ${word}` : word;
    if (textWidth(font, t) <= maxw || !cur) cur = t;
    else {
      lines.push(cur);
      cur = word;
    }
  }
  if (cur) lines.push(cur);
  return lines;
}

function fitText(text: string, font: FontKey, lh: number, aspect = 2.0, minw = 70, maxw = 250) {
  const total = textWidth(font, text);
  const tw = Math.max(minw, Math.min(maxw, Math.sqrt(total * lh * aspect)));
  const lines = wrap(text, font, tw);
  return { lines, tw: Math.max(0, ...lines.map((l) => textWidth(font, l))), th: lines.length * lh };
}

function isShout(t: string): boolean {
  const letters = [...t].filter((c) => /\p{L}/u.test(c));
  const caps = letters.filter((c) => /\p{Lu}/u.test(c)).length / Math.max(1, letters.length);
  return t.includes("?!") || t.includes("!!") || (t.trimEnd().endsWith("!") && caps > 0.5);
}

// ---------- geometry helpers ----------
function inter(a: Rect, b: Rect): number {
  return Math.max(0, Math.min(a[2], b[2]) - Math.max(a[0], b[0])) * Math.max(0, Math.min(a[3], b[3]) - Math.max(a[1], b[1]));
}

function pad(r: Rect, p: number): Rect {
  return [r[0] - p, r[1] - p, r[2] + p, r[3] + p];
}

// Python round(): half to even.
function pyRound(v: number): number {
  const r = Math.round(v);
  return Math.abs(v % 1) === 0.5 && r % 2 !== 0 ? r - 1 : r;
}

type Region = [number, number, number, number]; // centre ranges xmin, xmax, ymin, ymax
type Best = { s: number; cx: number; cy: number } | null;

function search(regions: Region[], score: (cx: number, cy: number) => number | null, step = 14): Best {
  let best: Best = null;
  for (const [x1, x2, y1, y2] of regions) {
    const xa = Math.min(x1, x2), xb = Math.max(x1, x2), ya = Math.min(y1, y2), yb = Math.max(y1, y2);
    const nx = Math.max(1, Math.floor((xb - xa) / step) + 1);
    const ny = Math.max(1, Math.floor((yb - ya) / step) + 1);
    for (let i = 0; i < nx; i++) {
      for (let j = 0; j < ny; j++) {
        const cx = xa + (xb - xa) * (i / Math.max(1, nx - 1));
        const cy = ya + (yb - ya) * (j / Math.max(1, ny - 1));
        const s = score(cx, cy);
        if (s !== null && (best === null || s < best.s)) best = { s, cx, cy };
      }
    }
  }
  return best;
}

function anchorRegion(anchor: string, x0: number, w: number, h: number, bw: number, bh: number): Region[] {
  const L = 6 + bw / 2, R = W - 6 - bw / 2;
  const mid = x0 + w / 2;
  const left: [number, number] = [L, mid], right: [number, number] = [mid, R], both: [number, number] = [L, R];
  const top: [number, number] = [bh * 0.1, h * 0.38], m: [number, number] = [h * 0.3, h * 0.7], bot: [number, number] = [h * 0.62, h + bh * 0.35];
  const A: Record<string, Region> = {
    "top-left": [...left, ...top], "top-right": [...right, ...top], top: [...both, ...top],
    left: [...left, ...m], right: [...right, ...m],
    "bottom-left": [...left, ...bot], "bottom-right": [...right, ...bot],
    "over-top-edge": [...both, -bh * 0.15, bh * 0.15], "over-bottom-edge": [...both, h - bh * 0.15, h + bh * 0.15],
    "gutter-above": [...both, -bh / 2 - 14, -bh / 2 - 14], "gutter-below": [...both, h + bh / 2 + 14, h + bh / 2 + 14],
  };
  return [A[anchor] ?? A.top!];
}

// ---------- panel geometry ----------
interface PanelBox { x: number; w: number; h: number; cropFrac: number | null }

/** Display box and, when the image is taller than the box, the visible height fraction (placed later around the focus). */
function panelBox(layout: string, iw: number, ih: number): PanelBox {
  const w = layout === "inset_left" || layout === "inset_right" ? 470 : W;
  const x = layout === "inset_right" ? W - w : 0;
  let h = pyRound((w * ih) / iw);
  if (layout === "tight_crop") h = 300;
  else if (layout === "wide_band") h = Math.min(h, 340);
  h = Math.min(h, layout !== "title" ? MAX_PANEL_H : 1050);
  const vis = (w / iw) * ih;
  return { x, w, h, cropFrac: h < vis - 1 ? h / vis : null };
}

function placeCrop(frac: number | null, focusY: number): Rect {
  if (frac === null) return [0, 0, 1, 1];
  const top = Math.min(Math.max(0, focusY - frac / 2), 1 - frac);
  return [0, top, 1, top + frac];
}

interface CharGeo { head: Point; face: Rect | null }

/** Head point + face box in normalized image coords from the NovelAI pin and framing. */
function charGeometry(c: LayoutCharacterIn, iw: number, ih: number): CharGeo {
  const fr = c.framing ?? "upper body";
  const hf = HEAD[fr];
  if (!hf) return { head: [c.x, Math.max(0.05, c.y - 0.25)], face: null };
  let [half, fh] = hf;
  if (fr !== "portrait") half = Math.min(half, c.y, 1 - c.y);
  const hy = Math.max(fh / 2 + 0.01, c.y - half + 0.6 * fh);
  const fw = ((fh * ih) / iw) * 1.3;
  return { head: [c.x, hy], face: [c.x - fw / 2, hy - fh / 2, c.x + fw / 2, hy + fh / 2] };
}

function gap(p: LayoutPanelIn, prev: LayoutPanelIn | null): number {
  if (prev === null) return 0;
  if (p.scene_change) return 230;
  if (p.beat === "quiet" || p.beat === "reaction" || p.kind === "text_beat") return 130;
  if (p.beat === "action") return 50;
  return 80;
}

function imageSize(p: LayoutPanelIn, sizes: LayoutInput["imageSizes"]): [number, number] {
  const s = sizes[String(p.id)];
  if (s) return [s.width, s.height];
  const m = /^(\d+)x(\d+)$/.exec(p.size ?? "");
  if (!m) throw new Error(`panel ${p.id}: no image size`);
  return [Number(m[1]), Number(m[2])];
}

function splitTitle(t: string): { small: string; big: string } {
  const i = t.indexOf(":");
  const a = i < 0 ? t : t.slice(0, i);
  const b = i < 0 ? "" : t.slice(i + 1);
  return b ? { small: a.trim().toUpperCase(), big: b.trim() } : { small: "", big: a.trim() };
}

// ---------- text placement (panel-local: y relative to the image top, x in strip coords) ----------
interface FacePx { head: Point; face: Rect | null }
interface PanelCtx { p: LayoutPanelIn; x0: number; w: number; h: number; facePx: Map<string, FacePx>; faces: Rect[]; placed: Rect[] }
type Local =
  | { kind: "speech" | "thought"; i: number; cx: number; cy: number; rx: number; ry: number; tw: number; th: number; lines: string[]; tail: Point | null; shout: boolean; rect: Rect; fallback: string | null }
  | { kind: "narration"; i: number; rect: Rect; lines: string[]; fallback: string | null }
  | { kind: "sfx"; i: number; cx: number; cy: number; big: boolean; rot: number; rect: Rect };

function placeBalloon(t: LayoutTextIn, i: number, ctx: PanelCtx, prevCy: number): Local {
  const { p, x0, w, h, facePx, faces, placed } = ctx;
  const shout = t.type === "speech" && isShout(t.text);
  const { lines, tw, th } = fitText(t.text, "speech", LH_SPEECH, 3.4, 96, 270);
  const k = shout ? 1.25 : 1.0;
  const rx = (tw / 2) * 1.32 * k + 12, ry = (th / 2) * 1.38 * k + 10;
  const bw = 2 * rx, bh = 2 * ry;
  let sp = t.speaker != null ? facePx.get(t.speaker) : undefined;
  if (sp && !sp.face) sp = undefined; // hands-only / lower-body shot: the speaker's head is off-panel
  const target = sp ? sp.head : null;
  const nballoons = p.text.filter((q) => q.type === "speech" || q.type === "thought").length;
  const anchor = t.anchor ?? "top";
  const score = (cx: number, cy: number): number | null => {
    const rect: Rect = [cx - rx * 0.92, cy - ry * 0.92, cx + rx * 0.92, cy + ry * 0.92];
    if (rect[0] < 4 || rect[2] > W - 4) return null;
    if (faces.some((f) => inter(rect, pad(f, 6)) > 0)) return null;
    if (placed.some((q) => inter(rect, pad(q, 8)) > 0)) return null;
    if (cy < prevCy + 30) return null; // reading order: each balloon lower than the previous one
    let s = 0;
    if (target) {
      const d = Math.hypot(cx - target[0], cy - target[1]) - Math.max(rx, ry);
      s += Math.max(0, 30 - d, d - 160) * 1.5; // balloon edge 30-160 px from the head: tail stays short
      s += cy * (nballoons > 1 ? 0.4 : 0.1); // high positions leave room below for the next balloon
      if (cy > target[1] + 40) s += 400; // balloons sit above/level with the speaker's head
    } else {
      s += Math.abs(cy - h * 0.15) * 0.3;
    }
    if (cy - ry < -bh * 0.6 || cy + ry > h + bh * 0.6) s += 150; // stay on the art
    return s;
  };
  let best = search(anchorRegion(anchor, x0, w, h, bw, bh), score);
  let fallback: string | null = null;
  if (best === null && target) {
    fallback = "side"; // same side as the anchor, any height down to the speaker's head
    const side: [number, number] = anchor.includes("left") ? [6 + rx, x0 + w / 2] : anchor.includes("right") ? [x0 + w / 2, W - 6 - rx] : [6 + rx, W - 6 - rx];
    best = search([[...side, bh * 0.1, target[1] + 20]], score);
  }
  if (best === null) {
    fallback = "anywhere";
    best = search([[6 + rx, W - 6 - rx, -bh, h + bh]], score);
  }
  if (best === null) {
    fallback = "gutter";
    best = { s: 0, cx: W / 2, cy: prevCy > -1e8 ? prevCy + bh + 20 : -bh / 2 - 14 };
  }
  const { cx, cy } = best;
  let tail: Point | null = null;
  if (target && sp?.face) {
    const fb = sp.face;
    // aim at the mouth area; stop short of the face box
    const aim: Point = [target[0], target[1] + (fb[3] - fb[1]) * 0.18];
    const dx = aim[0] - cx, dy = aim[1] - cy;
    const dist = Math.hypot(dx, dy) || 1;
    const edge = Math.hypot((rx * dx) / dist, (ry * dy) / dist); // approx radius toward the aim
    let stop = dist - 14;
    while (stop > edge && fb[0] - 4 < cx + (dx / dist) * stop && cx + (dx / dist) * stop < fb[2] + 4 && fb[1] - 4 < cy + (dy / dist) * stop && cy + (dy / dist) * stop < fb[3] + 4) stop -= 4;
    const len = Math.min(edge + 48, Math.max(edge + 14, stop));
    tail = [cx + (dx / dist) * len, cy + (dy / dist) * len];
  } else if (t.speaker) {
    // off-panel speaker: short tail out of the frame toward the nearest vertical edge
    tail = [cx + (rx + 24) * (cx < W / 2 ? -1 : 1) * 0.6, cy < h / 2 ? cy - ry - 20 : cy + ry + 20];
  }
  const kind = t.type === "thought" ? "thought" : "speech";
  return { kind, i, cx, cy, rx, ry, tw, th, lines, tail, shout, rect: [cx - rx, cy - ry, cx + rx, cy + ry], fallback };
}

function placeNarr(t: LayoutTextIn, i: number, ctx: PanelCtx): Local {
  const { x0, w, h, faces, placed } = ctx;
  const { lines, tw, th } = fitText(t.text, "narration", LH_NARR, 3.4, 70, 300);
  const bw = tw + 36, bh = th + 24;
  const a = t.anchor ?? "top-left";
  const left = !a.includes("right") ? [x0 + 14, Math.max(6, x0 - 30)] : [];
  const right = !a.includes("left") ? [x0 + w - bw - 14, Math.min(W - 6 - bw, x0 + w - bw + 30)] : [];
  const xs = left.length + right.length ? [...left, ...right] : [x0 + 14, x0 + w - bw - 14];
  const topYs = [-bh / 2, 14], botYs = [h - bh / 2, h - bh - 14];
  let ys = a.includes("bottom") ? botYs : a.includes("top") ? topYs : [...topYs, ...botYs];
  if (a === "over-top-edge") ys = [-bh / 2];
  if (a === "over-bottom-edge") ys = [h - bh / 2];
  const cands: Point[] = [
    ...ys.flatMap((y) => xs.map((x): Point => [x, y])),
    ...[...topYs, ...botYs].flatMap((y) => [x0 + 14, x0 + w - bw - 14].map((x): Point => [x, y])),
  ];
  for (const [x, y] of cands) {
    const r: Rect = [x, y, x + bw, y + bh];
    if (x < 4 || x + bw > W - 4) continue;
    if (faces.some((f) => inter(r, pad(f, 6)) > 0) || placed.some((q) => inter(r, pad(q, 8)) > 0)) continue;
    return { kind: "narration", i, rect: r, lines, fallback: null };
  }
  const y = h + 20;
  return { kind: "narration", i, rect: [x0 + 14, y, x0 + 14 + bw, y + bh], lines, fallback: "gutter" };
}

function placeSfx(t: LayoutTextIn, i: number, ctx: PanelCtx): Local {
  const { p, x0, w, h, faces, placed } = ctx;
  const big = p.beat === "action";
  const size = big ? 60 : 50;
  const tw = (textWidth("sfx", t.text) * size) / SFX_FONT_PX;
  const bw = tw + 10, bh = size + 10;
  const a = t.anchor ?? "bottom-left";
  const off = a === "gutter-above" || a === "gutter-below" || a === "over-top-edge" || a === "over-bottom-edge";
  // SFX live on the art: clamp the region inside the image
  const regs = anchorRegion(off ? "left" : a, x0, w, h, bw, bh).map(([xa, xb, ya, yb]): Region => [
    Math.max(xa, x0 + bw / 2 + 6), Math.min(xb, x0 + w - bw / 2 - 6), Math.max(ya, bh / 2 + 6), Math.min(yb, h - bh / 2 - 6),
  ]);
  const score = (cx: number, cy: number): number | null => {
    const r: Rect = [cx - bw / 2, cy - bh / 2, cx + bw / 2, cy + bh / 2];
    // wide margin: muzzles, hands and chins stick out of the face box
    if (faces.some((f) => inter(r, pad(f, 0.3 * (f[2] - f[0]))) > 0) || placed.some((q) => inter(r, pad(q, 6)) > 0)) return null;
    return 0;
  };
  const best = search(regs, score, 20) ?? search([[x0 + bw / 2 + 6, x0 + w - bw / 2 - 6, bh / 2 + 6, h - bh / 2 - 6]], score, 20);
  const [cx, cy] = best ? [best.cx, best.cy] : [x0 + w / 2, h - bh];
  return { kind: "sfx", i, cx, cy, big, rot: cx < W / 2 ? -10 : 8, rect: [cx - bw / 2, cy - bh / 2, cx + bw / 2, cy + bh / 2] };
}

// ---------- strip ----------
class StripBuilder {
  y = 0;
  sfxCount = 0;
  panels: LayoutPanel[] = [];
  items: LayoutItem[] = [];

  constructor(private readonly input: LayoutInput) {}

  run(): StripLayout {
    const panels = this.input.storyboard.panels;
    panels.forEach((p, i) => {
      this.y += gap(p, i > 0 ? panels[i - 1]! : null);
      if (p.kind === "image") this.imagePanel(p, i === 0);
      else this.textBeat(p);
    });
    this.y += 120;
    return { version: 1, width: W, height: Math.trunc(this.y), panels: this.panels, items: this.items };
  }

  private sfx(panelId: string, textIndex: number, text: string, cx: number, cy: number, big: boolean, rot: number) {
    const size = big ? 60 : 50;
    const color = SFX_COLORS[this.sfxCount++ % SFX_COLORS.length]!;
    const w = (textWidth("sfx", text) * size) / SFX_FONT_PX;
    this.items.push({ kind: "sfx", panelId, textIndex, text, lines: [text], rect: [cx - w / 2, cy - size / 2, cx + w / 2, cy + size / 2], cx, cy, size, rot, color });
  }

  // narration boxes staggered left/right on white
  private textBeat(p: LayoutPanelIn) {
    const panelId = String(p.id);
    let side = 0;
    p.text.forEach((t, i) => {
      if (t.type === "sfx") {
        this.sfx(panelId, i, t.text, W / 2, this.y + 40, true, -10);
        this.y += 110;
        return;
      }
      const { lines, tw, th } = fitText(t.text, "narration", LH_NARR, 3.2, 70, 330);
      const bw = tw + 40, bh = th + 28;
      const x = side === 0 ? 70 : W - 70 - bw;
      this.items.push({ kind: "narration", panelId, textIndex: i, text: t.text, lines, rect: [x, this.y, x + bw, this.y + bh], fallback: null });
      this.y += bh + 60;
      side ^= 1;
    });
  }

  private imagePanel(p: LayoutPanelIn, first: boolean) {
    const panelId = String(p.id);
    const layout = p.layout ?? "full_width";
    const [iw, ih] = imageSize(p, this.input.imageSizes);
    const { x: x0, w, h, cropFrac } = panelBox(layout, iw, ih);
    const geo = new Map<string, CharGeo>();
    for (const c of p.nai?.characters ?? []) geo.set(c.name, charGeometry(c, iw, ih));
    // crop focus: speakers' heads first, else all heads, else centre
    const speakers = p.text.filter((t) => t.type === "speech" || t.type === "thought").map((t) => t.speaker);
    let heads = speakers.flatMap((n) => (n != null && geo.has(n) ? [geo.get(n)!.head[1]] : []));
    if (!heads.length) heads = [...geo.values()].map((g) => g.head[1]);
    if (!heads.length) heads = [0.5];
    if (layout === "title") heads = [0.62];
    const crop = placeCrop(cropFrac, heads.reduce((a, b) => a + b, 0) / heads.length);
    const toPx = (nx: number, ny: number): Point => [x0 + nx * w, ((ny - crop[1]) / (crop[3] - crop[1])) * h];
    const facePx = new Map<string, FacePx>();
    for (const [n, g] of geo) {
      const f = g.face;
      facePx.set(n, { head: toPx(...g.head), face: f ? [...toPx(f[0], f[1]), ...toPx(f[2], f[3])] : null });
    }
    const ctx: PanelCtx = { p, x0, w, h, facePx, faces: [...facePx.values()].flatMap((v) => (v.face ? [v.face] : [])), placed: [] };
    const local: Local[] = [];
    let prevCy = -1e9;
    p.text.forEach((t, i) => {
      if (layout === "title" && t.type === "speech") return; // the title lettering owns the panel
      let r: Local;
      if (t.type === "speech" || t.type === "thought") {
        r = placeBalloon(t, i, ctx, prevCy);
        prevCy = r.kind === "speech" || r.kind === "thought" ? r.cy : prevCy;
      } else if (t.type === "narration") r = placeNarr(t, i, ctx);
      else r = placeSfx(t, i, ctx);
      ctx.placed.push(r.rect);
      local.push(r);
    });
    let top = Math.min(0, ...local.map((r) => r.rect[1] - 10));
    const bottom = Math.max(h, ...local.map((r) => r.rect[3] + 10));
    if (first && layout === "title") top = 0;
    const oy = this.y - top; // image top in strip coords
    const mask = layout === "fade_white" || layout === "title" ? "fade-bottom" : layout === "wide_band" && p.beat === "insert" ? "fade-sides" : null;
    const panel: LayoutPanel = { panelId, x: x0, y: oy, w, h, crop, mask };
    if (layout === "title") panel.title = { ...splitTitle(this.input.storyboard.title ?? ""), y: oy + h * 0.13 };
    this.panels.push(panel);
    for (const r of local) this.emit(panelId, p.text[r.i]!, r, oy);
    this.y = oy + bottom;
  }

  private emit(panelId: string, t: LayoutTextIn, r: Local, oy: number) {
    const base = { panelId, textIndex: r.i, text: t.text };
    if (r.kind === "sfx") {
      this.sfx(panelId, r.i, t.text, r.cx, r.cy + oy, r.big, r.rot);
    } else if (r.kind === "narration") {
      this.items.push({ ...base, kind: "narration", lines: r.lines, rect: [r.rect[0], r.rect[1] + oy, r.rect[2], r.rect[3] + oy], fallback: r.fallback });
    } else {
      const cy = r.cy + oy;
      this.items.push({
        ...base,
        kind: r.kind,
        lines: r.lines,
        rect: [r.rect[0], r.rect[1] + oy, r.rect[2], r.rect[3] + oy],
        fallback: r.fallback,
        cx: r.cx,
        cy,
        rx: r.rx,
        ry: r.ry,
        tail: r.tail ? [r.tail[0], r.tail[1] + oy] : null,
        shout: r.shout,
        speaker: t.speaker ?? null,
        textBox: { x: r.cx - r.tw / 2 - 4, y: cy - r.th / 2, w: r.tw + 8, h: r.th },
      });
    }
  }
}

export function layoutStrip(input: LayoutInput): StripLayout {
  return new StripBuilder(input).run();
}
